def mark_existing_orders(apps, schema_editor):
    """
    Проставляет источник существующим заказам.

    Признак заказа с сайта — комментарий вида
    «Заявка с сайта M-01079 от 21.11.2026 23:41», который пишет конвертация
    заявки. По номеру из комментария находим заявку и связываем с заказом.
    Все остальные заказы остаются в источнике «вручную» (значение по умолчанию).
    """
    Order = apps.get_model('orders', 'Order')
    WebOrder = apps.get_model('web_orders', 'WebOrder')

    for order in Order.objects.exclude(comment='').iterator():
        comment = order.comment or ''

        # Не наш заказ — оставляем как есть.
        if not comment.startswith('Заявка с сайта'):
            continue

        order.source = 'site'

        match = re.search(r'Заявка с сайта\s+(\S+)', comment)
        site_number = match.group(1) if match else ''

        if site_number:
            web_order = WebOrder.objects.filter(
                moguta_order_number=site_number
            ).first()

            if web_order is not None:
                # OneToOne: если заявка уже занята другим заказом
                # (бывает после ручных правок), связь не ставим.
                busy = Order.objects.filter(
                    web_order=web_order
                ).exclude(pk=order.pk).exists()

                if not busy:
                    order.web_order = web_order

        order.save(update_fields=['source', 'web_order'])


